const a=t=>{const n=(t.date??"").trim(),r=(t.line??"").trim(),e=t.head===""||t.head===void 0||t.head===null?"":String(t.head).trim(),s=(t.issue??"").trim(),o=(t.repaired??"").trim(),i=(t.notes??"").trim();return e?`H|${n}|${r}|${e}|${s}|${o}|${i}`:`MN|${n}|${r}|${i}`},c=t=>{let n=5381;for(let r=0;r<t.length;r++)n=(n<<5)+n^t.charCodeAt(r);return(n>>>0).toString(16)},d=t=>{const n=a(t);return`${n.startsWith("MN|")?"MN":"H"}_${c(n)}`};export{d as f};
